import Link from "next/link";
import {desc,eq,sql} from "drizzle-orm";
import {db} from "@/db";
import {rankedChallengeRuns,rankedChallenges} from "@/db/schema";
import {requireAdmin} from "@/lib/admin/authorization";
import {challengePhase} from "@/lib/challenges/policy";
import {AdminNav} from "@/components/admin/admin-nav";
import {getPreferences} from "@/lib/i18n/get-translations";

const label={DRAFT:"Bản nháp",UPCOMING:"Đã lên lịch",LIVE:"Đang diễn ra",CLOSED:"Đã kết thúc",CANCELLED:"Đã hủy"};
const typeLabel:Record<string,string>={READING_100:"Reading · 100 câu",LISTENING_100:"Listening · 100 câu",FULL_200:"Listening và Reading · 200 câu"};
export default async function Page(){const actor=await requireAdmin("CHALLENGE_MANAGE");const p=await getPreferences(actor.id);const vi=p.interfaceLanguage==="vi";const rows=await db.select({challenge:rankedChallenges,participants:sql<number>`count(${rankedChallengeRuns.id}) filter(where ${rankedChallengeRuns.status}='COMPLETED')::int`}).from(rankedChallenges).leftJoin(rankedChallengeRuns,eq(rankedChallengeRuns.challengeId,rankedChallenges.id)).groupBy(rankedChallenges.id).orderBy(desc(rankedChallenges.createdAt)).limit(100);return <main className="min-h-screen bg-slate-50 px-4 py-6 sm:px-6"><div className="mx-auto max-w-6xl"><AdminNav locale={p.interfaceLanguage}/><div className="mt-8 flex flex-wrap items-start justify-between gap-4"><div><h1 className="text-3xl font-black">{vi?"Sự kiện xếp hạng":"Ranking events"}</h1><p className="mt-2 max-w-3xl text-slate-600">{vi?"Tạo cuộc thi làm đề có thời gian giới hạn, mỗi người học một lượt. Bảng xếp hạng tuần vẫn hoạt động độc lập và không cần sự kiện.":"Create timed, one-attempt competitions. The weekly leaderboard works independently and does not require an event."}</p></div><Link className="rounded-xl bg-slate-900 px-4 py-3 font-bold text-white focus-visible:outline-2 focus-visible:outline-offset-2" href="/admin/challenges/new">{vi?"Tạo sự kiện":"Create event"}</Link></div>{rows.length?<div className="mt-7 grid gap-3">{rows.map(({challenge:c,participants})=>{const phase=challengePhase(c);return <Link className="rounded-2xl border bg-white p-5 hover:border-teal-400 focus-visible:outline-2" href={`/admin/challenges/${c.id}`} key={c.id}><div className="flex flex-wrap justify-between gap-2"><strong className="text-lg">{vi?c.titleVi:c.titleEn}</strong><span className="rounded-full bg-slate-100 px-3 py-1 text-sm font-bold">{vi?label[phase]:phase}</span></div><p className="mt-2 text-sm text-slate-600">{typeLabel[c.type]} · {c.startsAt?.toLocaleString(vi?"vi-VN":"en-US",{timeZone:"Asia/Ho_Chi_Minh"})} – {c.endsAt?.toLocaleString(vi?"vi-VN":"en-US",{timeZone:"Asia/Ho_Chi_Minh"})} (GMT+7) · {participants} {vi?"kết quả hoàn thành":"completed results"}</p></Link>})}</div>:<section className="mt-8 rounded-2xl border border-dashed bg-white p-8"><h2 className="text-xl font-bold">{vi?"Chưa có sự kiện nào":"No events yet"}</h2><p className="mt-2 text-slate-600">{vi?"Chỉ tạo sự kiện khi muốn tổ chức một cuộc thi Reading, Listening hoặc đề đầy đủ trong khoảng thời gian xác định. Người học vẫn có thể tích điểm RP trên bảng tuần mà không cần sự kiện.":"Create an event for a scheduled Reading, Listening, or full-test competition. Learners can earn weekly RP without one."}</p><Link className="mt-4 inline-block font-bold text-teal-700 underline" href="/admin/challenges/new">{vi?"Tạo sự kiện đầu tiên":"Create the first event"}</Link></section>}</div></main>}
